   177  int typesdb_add_field(struct typesdb_node *node, const char *field)
   178  {
   179      char *end;
   180      int alloc;
   181      char **fields;
   182
   183      end = strchr(field, ':');
   184      if (!end) {
   185          return -1;
   186      }
   187
   188      if (node->count >= node->alloc) {
   189          alloc = node->alloc > 0 ? node->alloc * 2 : 1;
   190          fields = flb_realloc(node->fields, alloc * sizeof(char *));
   191          if (!fields) {
   192              flb_errno();
   193              return -1;
   194          }
   195          node->alloc = alloc;
   196          node->fields = fields;
   197      }
   198
   199      node->fields[node->count] = flb_strndup(field, end - field);
   200      if (!node->fields[node->count]) {
   201          flb_errno();
   202          return -1;
   203      }
   204      node->count++;
   205      return 0;
   206  }
