   105  static int tdb_right(char c, struct mk_list *tdb, char *buf)
   106  {
   107      int len;
   108      struct typesdb_node *node = typesdb_last_node(tdb);
   109
   110      switch (c) {
   111          case ' ':
   112          case ',':
   113              if (typesdb_add_field(node, buf)) {
   114                  flb_error("[in_collectd] cannot add value '%s'", buf);
   115                  return TDB_INVALID;
   116              }
   117              return TDB_RIGHT_SEP;
   118          case '\r':
   119          case '\n':
   120              if (typesdb_add_field(node, buf)) {
   121                  flb_error("[in_collectd] cannot add value '%s'", buf);
   122                  return TDB_INVALID;
   123              }
   124              return TDB_INIT;
   125          default:
   126              len = strlen(buf);
   127              if (len >= MAX_LINE_SIZE - 1) {
   128                  flb_error("[in_collectd] line too long > %i", MAX_LINE_SIZE);
   129                  return TDB_INVALID;
